export function normalizePlaySessionStatus(raw: string): PlaySessionStatus {
  if (raw === 'scheduled' || raw === 'waiting') return 'waiting';
  if (raw === 'active' || raw === 'paused' || raw === 'completed') return raw;
  throw new Error(`Unbekannter Session-Status: ${raw}`);
}

export interface SessionPresenceEntry {
  userId: string;
  characterId: string | null;
  isOnline: boolean;
  joinedAt: string;
}

export interface SessionGameplayState {
  sceneId: string | null;
  combatActive: boolean;
  shared: Record<string, unknown>;
}

export interface SessionRuntimeState {
  sessionId: string;
  revision: number;
  status: PlaySessionStatus;
  roster: SessionPresenceEntry[];
  gameplay: SessionGameplayState;
  updatedAt: string;
}

export class StaleRuntimeRevisionError extends Error {
  readonly expected: number;
  readonly actual: number;

  constructor(expected: number, actual: number) {
    super(`Veraltete Session-Revision: erwartet ${expected}, aktuell ${actual}`);
    this.name = 'StaleRuntimeRevisionError';
    this.expected = expected;
    this.actual = actual;
  }
}

export function isSessionEventKind(value: string): value is SessionEventKind {
  return (EVENT_KINDS as readonly string[]).includes(value);
}

export function assertSessionEventKind(value: string): SessionEventKind {
  if (!isSessionEventKind(value)) {
    throw new Error(`Unbekannte Session-Event-Art: ${value}`);
  }
  return value;
}

export function emptyGameplayState(): SessionGameplayState {
  return { sceneId: null, combatActive: false, shared: {} };
}

export function normalizeRuntimeStatus(raw: string): PlaySessionStatus {
  return normalizePlaySessionStatus(raw);
}

type SnapshotJson = {
  sessionId?: string;
  revision?: number;
  status?: string;
  roster?: unknown;
  gameplay?: unknown;
  updatedAt?: string;
  idempotentReplay?: boolean;
  eventId?: string;
};

function mapRoster(raw: unknown): SessionPresenceEntry[] {
  if (!Array.isArray(raw)) return [];
  const out: SessionPresenceEntry[] = [];
  for (const item of raw) {
    if (!item || typeof item !== 'object') continue;
    const row = item as Record<string, unknown>;
    const userId = typeof row.userId === 'string' ? row.userId : null;
    if (!userId) continue;
    out.push({
      userId,
      characterId: typeof row.characterId === 'string' ? row.characterId : null,
      isOnline: row.isOnline === true,
      joinedAt: typeof row.joinedAt === 'string' ? row.joinedAt : new Date(0).toISOString(),
    });
  }
  return out;
}

function mapGameplay(raw: unknown): SessionGameplayState {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    return emptyGameplayState();
  }
  const row = raw as Record<string, unknown>;
  const sceneId = typeof row.sceneId === 'string' && row.sceneId.trim() !== '' ? row.sceneId : null;
  const combatActive = row.combatActive === true;
  const sharedRaw = row.shared;
  const shared =
    sharedRaw && typeof sharedRaw === 'object' && !Array.isArray(sharedRaw)
      ? (sharedRaw as Record<string, unknown>)
      : {};
  return { sceneId, combatActive, shared };
}

export function mapSnapshotJson(data: SnapshotJson): SessionRuntimeState {
  const sessionId = typeof data.sessionId === 'string' ? data.sessionId : '';
  if (!sessionId) {
    throw new Error('Runtime-Snapshot ohne sessionId');
  }
  const revision = typeof data.revision === 'number' ? data.revision : Number(data.revision ?? 0);
  if (!Number.isFinite(revision)) {
    throw new Error('Runtime-Snapshot ohne gültige Revision');
  }
  return {
    sessionId,
    revision,
    status: normalizeRuntimeStatus(typeof data.status === 'string' ? data.status : 'waiting'),
    roster: mapRoster(data.roster),
    gameplay: mapGameplay(data.gameplay),
    updatedAt: typeof data.updatedAt === 'string' ? data.updatedAt : new Date().toISOString(),
  };
}

function isStaleRpcError(message: string): boolean {
  const lower = message.toLowerCase();
  return lower.includes('stale revision') || lower.includes('40001');
}

