export async function assertSupabaseJwtSession(): Promise<string> {
  const deadline = Date.now() + JWT_WAIT_MS;
  while (Date.now() <= deadline) {
    const sessionResult = await raceWithTimeoutOrSymbol(
      supabase.auth.getSession(),
      AUTH_SESSION_TIMEOUT_MS,
    );
    if (!isTimedOut(sessionResult)) {
      const session = sessionResult.data.session;
      const userId = session?.user?.id?.trim();
      if (session?.access_token && userId) {
        return userId;
      }
    }
    await new Promise<void>((resolve) => {
      window.setTimeout(resolve, JWT_POLL_MS);
    });
  }
  throw new Error(API_AUTH_REQUIRED_DE);
}

export function isTimedOut<T>(value: T | TimedOut): value is TimedOut {
  return value === TIMED_OUT;
}

export function raceWithTimeoutOrSymbol<T>(promise: PromiseLike<T>, ms: number): Promise<T | TimedOut> {
  return Promise.race([
    Promise.resolve(promise),
    new Promise<TimedOut>((resolve) => {
      window.setTimeout(() => resolve(TIMED_OUT), ms);
    }),
  ]);
}

