export async function getAuthenticatedUserId(): Promise<string> {
  if (isLocalAdminSession()) {
    const sessionResult = await raceWithTimeoutOrSymbol(
      supabase.auth.getSession(),
      AUTH_SESSION_TIMEOUT_MS,
    );
    if (!isTimedOut(sessionResult) && sessionResult.data.session?.user) {
      return sessionResult.data.session.user.id;
    }
    return LOCAL_ADMIN_USER_ID;
  }

  const { data, error } = await raceWithTimeoutReject(
    supabase.auth.getUser(),
    SUPABASE_QUERY_TIMEOUT_MS,
    'Authentication request timed out',
  );
  if (error) throw error;
  if (data.user) return data.user.id;
  throw new Error('User not authenticated');
}

export function isLocalAdminEnabled(): boolean {
  return import.meta.env.DEV === true;
}

export function isLocalAdminSession(): boolean {
  if (!isLocalAdminEnabled()) return false;
  if (typeof window === 'undefined') return false;
  if (window.localStorage.getItem(LOCAL_ADMIN_STORAGE_KEY) === 'true') return true;
  if (window.localStorage.getItem(LEGACY_LOCAL_ADMIN_STORAGE_KEY) === 'true') {
    window.localStorage.setItem(LOCAL_ADMIN_STORAGE_KEY, 'true');
    return true;
  }
  return false;
}

export function isTimedOut<T>(value: T | TimedOut): value is TimedOut {
  return value === TIMED_OUT;
}

export function raceWithTimeoutOrSymbol<T>(promise: PromiseLike<T>, ms: number): Promise<T | TimedOut> {
  return Promise.race([
    Promise.resolve(promise),
    new Promise<TimedOut>((resolve) => {
      window.setTimeout(() => resolve(TIMED_OUT), ms);
    }),
  ]);
}

export function raceWithTimeoutReject<T>(promise: PromiseLike<T>, ms: number, message: string): Promise<T> {
  return Promise.race([
    Promise.resolve(promise),
    new Promise<T>((_, reject) => {
      window.setTimeout(() => reject(new Error(message)), ms);
    }),
  ]);
}

