export interface SessionDto {
  id: string;
  /** Immutable public session id (SE-XXXXX). Empty until migration backfill. */
  public_id?: string;
  project_id: string;
  /** Immutable order within a saga — not the resource identity. */
  session_number: number;
  name: string | null;
  notes: string | null;
  status: ProjectSessionStatus;
  started_at: string | null;
  ended_at: string | null;
  duration_minutes: number | null;
  /** Optional session Look override (#349). Null/omitted → inherit saga default. */
  look_profile_id?: string | null;
  created_at: string;
  updated_at: string;
}

export interface SessionVm {
  id: string;
  publicId: string;
  projectId: string;
  sessionNumber: number;
  name: string | null;
  notes: string | null;
  status: ProjectSessionStatus;
  startedAt: string | null;
  endedAt: string | null;
  durationMinutes: number | null;
  /** Optional session Look override (#349). Null → inherit saga. */
  lookProfileId: string | null;
  createdAt: string;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function isSessionStatus(value: unknown): value is SessionDto['status'] {
  return (
    value === 'scheduled'
    || value === 'waiting'
    || value === 'active'
    || value === 'paused'
    || value === 'completed'
    || value === 'cancelled'
  );
}

function isSessionDto(value: unknown): value is SessionDto {
  if (!isRecord(value)) return false;
  const durationOk =
    value.duration_minutes === undefined
    || typeof value.duration_minutes === 'number'
    || value.duration_minutes === null;
  const publicIdOk =
    typeof value.public_id === 'string'
    || value.public_id === undefined
    || value.public_id === null;
  const lookOk =
    value.look_profile_id === undefined
    || value.look_profile_id === null
    || typeof value.look_profile_id === 'string';
  const notesOk =
    value.notes === undefined
    || typeof value.notes === 'string'
    || value.notes === null;
  return (
    typeof value.id === 'string'
    && publicIdOk
    && typeof value.project_id === 'string'
    && typeof value.session_number === 'number'
    && (typeof value.name === 'string' || value.name === null)
    && notesOk
    && isSessionStatus(value.status)
    && (typeof value.started_at === 'string' || value.started_at === null)
    && (typeof value.ended_at === 'string' || value.ended_at === null)
    && durationOk
    && lookOk
    && typeof value.created_at === 'string'
    && typeof value.updated_at === 'string'
  );
}

function normalizeSessionDto(value: SessionDto): SessionDto {
  return {
    ...value,
    // #569: notes column not selectable by authenticated — treat missing as null.
    notes: value.notes ?? null,
    duration_minutes: value.duration_minutes ?? null,
  };
}

